using Jellyfin.Data.Entities; using Jellyfin.Data.Enums; using MediaBrowser.Controller.Entities; using MediaBrowser.Controller.Entities.TV; using MediaBrowser.Controller.Library; namespace Jellyfin.Plugin.Randomizer.Services; public interface IRandomSource{int Next(int maxExclusive);} public sealed class SystemRandomSource:IRandomSource{public int Next(int maxExclusive)=>Random.Shared.Next(maxExclusive);} public sealed class RandomHistoryService{readonly object gate=new(); readonly Dictionary<Guid,LinkedList<Guid>> data=new(); public IReadOnlyCollection<Guid> Get(Guid u,int max){lock(gate)return data.TryGetValue(u,out var h)?h.Take(max).ToArray():Array.Empty<Guid>();} public void Add(Guid u,Guid id,int max){if(max<=0)return;lock(gate){if(!data.TryGetValue(u,out var h))data[u]=h=new();var n=h.Find(id);if(n!=null)h.Remove(n);h.AddFirst(id);while(h.Count>max)h.RemoveLast();}}} public sealed class RandomizerService{readonly ILibraryManager lib;readonly IRandomSource rnd;readonly RandomHistoryService hist; public RandomizerService(ILibraryManager l,IRandomSource r,RandomHistoryService h){lib=l;rnd=r;hist=h;} public IReadOnlyList<LibraryDto> Libraries(User u){return lib.GetUserRootFolder().Children.OfType<CollectionFolder>().Where(x=>x.IsVisibleStandalone(u)).Select(x=>new LibraryDto(x.Id,x.Name)).OrderBy(x=>x.Name,StringComparer.OrdinalIgnoreCase).ToArray();} public IReadOnlyList<LibraryDto> Search(User u,Guid? lid,string type,string? term,int limit){var k=type.Equals("Movie",StringComparison.OrdinalIgnoreCase)?BaseItemKind.Movie:BaseItemKind.Series;var q=Query(u,k,lid,null,WatchedFilter.All);q.SearchTerm=string.IsNullOrWhiteSpace(term)?null:term.Trim();q.Limit=Math.Clamp(limit,1,100);q.EnableTotalRecordCount=false;return lib.GetItemList(q).Select(x=>new LibraryDto(x.Id,x.Name)).ToArray();} public RandomizeResult? Randomize(User u,RandomizeRequest r){var recent=hist.Get(u.Id,Math.Clamp(r.AvoidRecent,0,20));BaseItem? x=r.Mode switch{RandomizationMode.RandomMovie=>Pick(u,BaseItemKind.Movie,r.LibraryId,r.ItemIds,r.Watched,recent,false),RandomizationMode.RandomShow=>Pick(u,BaseItemKind.Series,r.LibraryId,r.ItemIds,r.Watched,recent,false),RandomizationMode.RandomEpisode=>PickEpisode(u,r,recent),_=>null};if(x==null)return null;hist.Add(u.Id,x.Id,Math.Clamp(r.AvoidRecent,0,20));var e=x as Episode;return new RandomizeResult{ItemId=x.Id,ItemType=x.GetType().Name,Name=x.Name,SeriesName=e?.SeriesName,SeasonNumber=e?.ParentIndexNumber,EpisodeNumber=e?.IndexNumber,Overview=x.Overview,Year=x.ProductionYear};} BaseItem? PickEpisode(User u,RandomizeRequest r,IReadOnlyCollection<Guid> recent){var shows=r.ItemIds.Count>0?r.ItemIds.ToArray():lib.GetItemList(Query(u,BaseItemKind.Series,r.LibraryId,r.Watched)).Where(x=>!recent.Contains(x.Id)).Select(x=>x.Id).ToArray();if(shows.Length==0)return null;if(r.Strategy==RandomizationStrategy.EqualShow){foreach(var id in shows.OrderBy(_=>rnd.Next(int.MaxValue))){var e=Pick(u,BaseItemKind.Episode,null,new[]{id},r.Watched,recent,true);if(e!=null)return e;}return null;}return Pick(u,BaseItemKind.Episode,null,shows,r.Watched,recent,true);} BaseItem? Pick(User u,BaseItemKind k,Guid? lid,IReadOnlyCollection<Guid> ids,WatchedFilter w,IReadOnlyCollection<Guid> recent,bool idsAreAncestors){var q=Query(u,k,lid,w);if(ids.Count>0){if(idsAreAncestors)q.AncestorIds=ids.ToArray();else q.ItemIds=ids.ToArray();}if(recent.Count>0)q.ExcludeItemIds=recent.ToArray();q.EnableTotalRecordCount=true;q.StartIndex=null;q.Limit=null;var count=lib.GetItemsResult(q).TotalRecordCount;if(count<=0)return null;q.StartIndex=rnd.Next(count);q.Limit=1;q.EnableTotalRecordCount=false;return lib.GetItemList(q).FirstOrDefault();} static InternalItemsQuery Query(User u,BaseItemKind k,Guid? lid,WatchedFilter w){var q=new InternalItemsQuery(u){IncludeItemTypes=new[]{k},IsFolder=false,Recursive=true,IsPlayed=w switch{WatchedFilter.Watched=>true,WatchedFilter.Unwatched=>false,_=>null}};if(lid.HasValue)q.AncestorIds=new[]{lid.Value};return q;} }